for (size_t i = start; i < end; ++i) {
    Particle& pi = particles[i];
    float pressureForceX = 0.0f;
    float pressureForceY = 0.0f;
    float viscosityForceX = 0.0f;
    float viscosityForceY = 0.0f;

    float px = pi.x;
    float py = pi.y;

    // Determine grid cell coordinates for the particle
    int cellX = static_cast<int>(std::floor(px / h));
    int cellY = static_cast<int>(std::floor(py / h));

    // Search neighboring cells (3x3 grid)
    for (int dx = -1; dx <= 1; ++dx) {
        for (int dy = -1; dy <= 1; ++dy) {
            uint32_t cellHash = (static_cast<uint32_t>(cellX + dx) * 73856093) ^ 
                               (static_cast<uint32_t>(cellY + dy) * 19349663);
            uint32_t tableIdx = cellHash % particleCount;

            // Traverse the linked list in the hash table
            uint32_t neighborIdx = particleTable[tableIdx];
            while (neighborIdx != 0xFFFFFFFF) {
                if (neighborIdx != i) {
                    Particle& pj = particles[neighborIdx];
                    float diffX = px - pj.x;
                    float diffY = py - pj.y;
                    float distSq = diffX * diffX + diffY * diffY;

                    if (distSq < h2 && distSq > 0.0f) {
                        float dist = std::sqrt(distSq);
                        float weight = h - dist;

                        // Pressure force: -grad(P)
                        // F_pressure = -sum( m * (Pi + Pj)/(2*rho_j) * grad(W_spiky) )
                        float pressureMag = mass * (pi.pressure + pj.pressure) / (2.0f * pj.density) * spikyGrad * weight * weight;
                        pressureForceX -= (diffX / dist) * pressureMag;
                        pressureForceY -= (diffY / dist) * pressureMag;

                        // Viscosity force: mu * laplacian(v)
                        // F_viscosity = mu * sum( m * (vj - vi)/rho_j * laplacian(W_viscosity) )
                        float viscosityMag = viscosity * mass * spikyLap * weight / pj.density;
                        viscosityForceX += (pj.vx - pi.vx) * viscosityMag;
                        viscosityForceY += (pj.vy - pi.vy) * viscosityMag;
                    }
                }
                // This assumes the Particle struct contains a 'next' pointer for the hash table
                neighborIdx = pj.next; 
            }
        }
    }

    pi.fx += pressureForceX + viscosityForceX;
    pi.fy += pressureForceY + viscosityForceY;
}
// END_CODE

